import json,re
from pathlib import Path
r=Path(__file__).parent
old=json.loads(Path('simulation-population-report/source/simulation-renderer-population-results.json').read_text());third=json.loads(Path('simulation-paired/third-fps.json').read_text());assert len(third['results'])==7
by={x['scenario']['populationKey']:x for x in third['results']};points=[]
for pair in old['pairs']:
 x=by[pair['scenario']];assert not x.get('failure') and not x['errors'];assert x['after']['activeAnimals']==pair['units'];points.append({'units':pair['units'],'before':pair['before']['fps'],'after':pair['after']['fps'],'third':x['fps']})
old['thirdAttempt']={'name':'Optimized renderer + neighbor reuse','method':'Later 20-second FPS samples, five-second warmup, same seven saved fixtures, pinned original modules and camera settings; only ranch-life and ranch-navigation updated for neighbor reuse and hidden-pose bookkeeping. Shared-machine load differs from original measurements; differences cannot be attributed solely to the change.','measurements':third}
old['method']['units']='Actual animal assets on x-axis, plus 11 human actors: 3 household residents (2 adults and 1 child), plus 8 visiting farmhands. Static scene assets are not counted.'
(r/'source/simulation-renderer-population-results.json').write_text(json.dumps(old,indent=2))
s=Path('simulation-population-report/source/simulation-performance.html').read_text();s=s.replace('Before & after · FPS vs units','Ranch · FPS vs asset count')
a=s.index('<div class="legend">');b=s.index('<details id="page-context">',a)
series=[('before','1 · Original renderer','#ae513c'),('after','2 · Optimized renderer','#26786c'),('third','3 · Neighbor reuse','#5265bc')]
s=s[:a]+'<div class="legend">'+''.join(f'<span><i class="dot" style="background:{c}"></i>{label}</span>' for _,label,c in series)+'</div><p class="digest"><b>Three attempts · animal asset count × FPS.</b> Third curve measured later on shared hardware; timing differences are not a controlled speedup estimate.</p><div class="values"><table><thead><tr><th>Animal assets</th>'+''.join(f'<th>{p["units"]:,}</th>' for p in points)+'</tr></thead><tbody>'+''.join('<tr><th>'+label+'</th>'+''.join(f'<td>{p[key]:.1f}</td>' for p in points)+'</tr>' for key,label,c in series)+'</tbody></table></div><details><summary>Population, method & limitations</summary><p>The x-axis counts actual animal bodies, not buildings or scenery. Each scene also contains 11 human actors: two adult residents, one child and eight visiting farmhands. The ranch generator estimates one carer per six animals, subtracts residents assigned to care, and caps visiting help at eight. This is an existing staffing rule, not a validated capacity target.</p><p>The first two curves retain the original paired renderer measurements. The third is a later FPS run with the same saved scenes, pinned modules, daylight, camera, 1× speed, 1280×720 viewport, five-second warmup and 20-second sample. It adds nearby-peer reuse and hidden-pose bookkeeping skips to the optimized renderer. Machine contention and run timing differ, so this is not evidence that the code change alone caused the FPS difference. Raw load averages, frame intervals, simulation progress and hashes are retained.</p><p>Dashed segments mark the switch from a single tile to expanded layouts above 395 animals. Layout complexity changes too. Existing care/resource and placement/access limitations remain. <a href="/simulation-renderer-population-results.json">Measurements and source evidence</a></p></details>'+s[b:]
a=s.index('<script>const points=');b=s.index('</script>',a)+9
js='''<script>const points=POINTS,series=SERIES;function redraw(){const box=document.querySelector('.chart'),w=Math.min(960,box.clientWidth),mobile=w<600,h=mobile?310:430,L=mobile?38:60,R=w-42,T=35,B=h-65,max=Math.max(10,Math.ceil(Math.max(...points.flatMap(p=>series.map(([k])=>p[k])))/10)*10),X=n=>L+n/1000*(R-L),Y=n=>B-n/max*(B-T);let a=[];for(let y=0;y<=max;y+=10)a.push(`<line x1="${L}" x2="${R}" y1="${Y(y)}" y2="${Y(y)}" stroke="#ddd5c4"/><text x="${L-9}" y="${Y(y)+4}" text-anchor="end">${y}</text>`);for(const x of [0,250,500,750,1000])a.push(`<text x="${X(x)}" y="${B+24}" text-anchor="middle">${x.toLocaleString()}</text>`);a.push(`<text x="8" y="18">FPS</text><text x="${w/2}" y="${h-10}" text-anchor="middle">Animal asset count (+11 people)</text>`);for(const [key,label,color]of series){for(const [group,dash]of [[points.slice(0,4),false],[points.slice(3,5),true],[points.slice(4),false]])a.push(`<polyline fill="none" stroke="${color}" stroke-width="3" ${dash?'stroke-dasharray="5 6"':''} points="${group.map(p=>X(p.units)+','+Y(p[key])).join(' ')}"/>`);for(const p of points)a.push(`<circle cx="${X(p.units)}" cy="${Y(p[key])}" r="${key==='third'?4:5}" fill="${color}"><title>${label}: ${p.units} animals, ${p[key].toFixed(1)} FPS</title></circle>`);}box.innerHTML=`<svg viewBox="0 0 ${w} ${h}" role="img" aria-label="Three attempts: animal asset count versus FPS through 1000">${a.join('')}</svg>`;box.querySelectorAll('text').forEach(t=>t.style.fontSize=mobile?'11px':'14px')}addEventListener('resize',redraw);redraw();</script>'''.replace('POINTS',json.dumps(points)).replace('SERIES',json.dumps(series))
s=s[:a]+js+s[b:];s=s.replace('tbody tr:last-child{color:#26786c','tbody tr:last-child{color:#5265bc');(r/'source/simulation-performance.html').write_text(s);print(points)
